84	static void create_title(void)
85	{
86	    ui_title = lv_label_create(ui_bg);
87	    lv_label_set_text(ui_title, "APPS");
88	    lv_obj_set_style_text_font(ui_title, &lv_font_montserrat_28, 0);
89	    lv_obj_set_style_text_color(ui_title, COLOR_CYAN, 0);
