159	/* ========== 公开API ========== */
160	void app_launcher_create(lv_obj_t *parent)
161	{
162	    /* parent == 调用方传入的 appListCenter：设成铺满 watchScr、透明、不裁剪，
163	     * 让 455×455 的圆形 ui_bg 能正确居中，并配合 watch_start.c 的滑入动画（translate_y 作用于 parent）。 */
164	    lv_obj_set_size(parent, SCREEN_W, SCREEN_H);
165	    lv_obj_align(parent, LV_ALIGN_CENTER, 0, 0);
166	    lv_obj_set_style_bg_opa(parent, LV_OPA_TRANSP, 0);
167	    lv_obj_set_style_border_width(parent, 0, 0);
168	    lv_obj_set_style_pad_all(parent, 0, 0);
169	    lv_obj_clear_flag(parent, LV_OBJ_FLAG_SCROLLABLE);
170	
171	    create_background(parent);
172	    create_title();
173	    for (int8_t i = 0; i < APP_COUNT; i++) create_app_card(i);
174	    /* 初始全部默认态（不预选高亮） */
175	    for (int8_t i = 0; i < APP_COUNT; i++) set_card_default(i);
176	    selected_idx = 0;
177	    ui_group = lv_group_create();
178	    for (int8_t i = 0; i < APP_COUNT; i++) lv_group_add_obj(ui_group, ui_cards[i]);
179	}
180	
181	void app_launcher_next(void)  { selected_idx = (selected_idx+1) % APP_COUNT; for(int8_t i=0;i<APP_COUNT;i++) set_card_default(i); set_card_pressed(selected_idx); }
182	void app_launcher_prev(void)  { selected_idx = (selected_idx-1+APP_COUNT) % APP_COUNT; for(int8_t i=0;i<APP_COUNT;i++) set_card_default(i); set_card_pressed(selected_idx); }
183	void app_launcher_enter(void) { if (apps[selected_idx].launch_cb) apps[selected_idx].launch_cb(); }
184	int8_t app_launcher_get_selected(void) { return selected_idx; }
185	lv_group_t *app_launcher_get_group(void) { return ui_group; }
186	
187	void app_launcher_delete(void)
188	{
189	    if (ui_group) { lv_group_del(ui_group); ui_group = NULL; }
190	    if (ui_bg) { lv_obj_del(ui_bg); ui_bg = NULL; }
191	    /* 清空卡片/图标/名称数组引用，防悬空指针 */
192	    for (int8_t i = 0; i < APP_COUNT; i++) {
193	        ui_cards[i] = NULL; ui_icons[i] = NULL; ui_names[i] = NULL;
194	    }
195	    ui_ring = NULL; ui_title = NULL;
196	    selected_idx = 0;
197	}
