199	/* ========== 旧 API 适配：供 watch_start.c 页面栈调用 ==========
200	 * applist_create_list: 左滑/返回时建列表，内部委托 app_launcher_create。
201	 * applist_hide_page:   右滑/进二级页删列表前清理静态引用（group + ui_bg 子树），
202	 *                      调用方随后 lv_obj_delete(appListCenter) 删容器壳。 */
203	lv_obj_t *applist_create_list(lv_obj_t *scr)
204	{
205	    app_launcher_create(scr);
206	    return scr;
207	}
208	
209	void applist_hide_page(void)
210	{
211	    app_launcher_delete();  /* 删 group + ui_bg 子树，清空静态指针 */
212	    LV_LOG_USER("applist_hide_page: launcher cleaned");
213	}

