49	/* 隐藏表盘：加 LV_OBJ_FLAG_HIDDEN 让 LVGL 整棵跳过表盘绘制（省 CPU）。
50	 * 关键：不暂停 timer！表盘虽不绘制，指针角度仍每秒更新；右滑 clear HIDDEN 时
51	 * 秒针已是当前正确角度，无定格→跳变。timer 持续写属性对隐藏对象是轻活（不触发渲染）。 */
52	static void watch_hide(void)
53	{
54	    if (mpd && mpd->mainPage) {
55	        lv_obj_add_flag(mpd->mainPage, LV_OBJ_FLAG_HIDDEN);
56	    }
57	}
