131	void watch_update_time(lv_timer_t *timer)
132	{
133	    time_t t = time(NULL);
134	    struct tm *localTime = localtime(&t);
135	    uint16_t hour = (localTime->tm_hour + 8) % 24;
136	    uint16_t minute = localTime->tm_min;
137	    uint16_t second = localTime->tm_sec;
138	
139	    /* _1 指针图(16x455)的旋转轴心在图正中(w/2, h/2)。
140	     * lv_obj_center 已把图中心对齐表盘中心 → pivot=图中心=表盘中心，
141	     * 不再 set_pos（加 set_pos 反而把图挪偏，之前"中心偏移"就是这原因）。
142	     * LVGL v9 angle 0.1°：秒*60 | 分*60+秒 | (hour%12)*300+分*5 */
143	    int second_w = lv_obj_get_width(g_ui.second_hand);
144	    int second_h = lv_obj_get_height(g_ui.second_hand);
145	    lv_image_set_pivot(g_ui.second_hand, second_w / 2, second_h / 2);
146	    lv_image_set_zoom(g_ui.second_hand, 170);
147	    lv_image_set_rotation(g_ui.second_hand, second * 60);
148	
149	    int minute_w = lv_obj_get_width(g_ui.minute_hand);
150	    int minute_h = lv_obj_get_height(g_ui.minute_hand);
151	    lv_image_set_pivot(g_ui.minute_hand, minute_w / 2, minute_h / 2);
152	    lv_image_set_zoom(g_ui.minute_hand, 170);
153	    lv_image_set_rotation(g_ui.minute_hand, minute * 60 + second);
154	
155	    int hour_w = lv_obj_get_width(g_ui.hour_hand);
156	    int hour_h = lv_obj_get_height(g_ui.hour_hand);
157	    lv_image_set_pivot(g_ui.hour_hand, hour_w / 2, hour_h / 2);
158	    lv_image_set_zoom(g_ui.hour_hand, 170);
159	    lv_image_set_rotation(g_ui.hour_hand, (hour % 12) * 300 + minute * 5);
160	}
