114	    lv_obj_set_style_text_font(ui_icons[idx], &lv_font_montserrat_32, 0);
115	    lv_obj_align(ui_icons[idx], LV_ALIGN_LEFT_MID, 28, 0);
116	
117	    /* 名称在图标右侧，中文字体 */
118	    ui_names[idx] = lv_label_create(ui_cards[idx]);
119	    lv_label_set_text(ui_names[idx], apps[idx].name);
120	    lv_obj_set_style_text_font(ui_names[idx], font_manager_get_font(FONT_LARGE), 0);  /* 中文 24 号 */
121	    lv_obj_align(ui_names[idx], LV_ALIGN_LEFT_MID, 80, 0);
122	
123	    lv_obj_add_event_cb(ui_cards[idx], card_event_cb, LV_EVENT_ALL, (void*)(intptr_t)idx);
124	}
125	
126	/* ========== 卡片样式：默认态 / 按下态 ==========
127	 * 默认低亮；按下(PRESSED)给高亮反馈，松开(RELEASED)还原——不保留持续高亮。 */
128	static void set_card_default(int8_t i)
129	{
130	    lv_obj_set_style_border_color(ui_cards[i], COLOR_PURPLE, 0);
131	    lv_obj_set_style_border_width(ui_cards[i], 2, 0);
132	    lv_obj_set_style_bg_color(ui_cards[i], COLOR_PURPLE, 0);
133	    lv_obj_set_style_bg_opa(ui_cards[i], LV_OPA_10, 0);
134	    lv_obj_set_style_text_color(ui_icons[i], COLOR_PURPLE, 0);
135	    lv_obj_set_style_text_color(ui_names[i], COLOR_GRAY, 0);
136	}
137	
138	static void set_card_pressed(int8_t i)
139	{
140	    lv_obj_set_style_border_color(ui_cards[i], COLOR_CYAN, 0);
141	    lv_obj_set_style_border_width(ui_cards[i], 3, 0);
142	    lv_obj_set_style_bg_color(ui_cards[i], COLOR_CYAN, 0);
143	    lv_obj_set_style_bg_opa(ui_cards[i], LV_OPA_30, 0);
144	    lv_obj_set_style_text_color(ui_icons[i], COLOR_CYAN, 0);
145	    lv_obj_set_style_text_color(ui_names[i], COLOR_WHITE, 0);
146	}
147	
148	static void card_event_cb(lv_event_t *e)
149	{
150	    lv_event_code_t code = lv_event_get_code(e);
151	    int8_t idx = (int8_t)(intptr_t)lv_event_get_user_data(e);
152	    if (code == LV_EVENT_PRESSED) {
153	        set_card_pressed(idx);        /* 按下即高亮 */
154	    } else if (code == LV_EVENT_RELEASED || code == LV_EVENT_PRESS_LOST) {
155	        set_card_default(idx);        /* 松开/失去按下即还原 */
156	    } else if (code == LV_EVENT_CLICKED) {
157	        if (apps[idx].launch_cb) apps[idx].launch_cb();
158	    }
159	}
160	
161	/* ========== 公开API ========== */
162	void app_launcher_create(lv_obj_t *parent)
163	{
164	    /* parent == 调用方传入的 appListCenter：设成铺满 watchScr、透明、不裁剪，
165	     * 让 455×455 的圆形 ui_bg 能正确居中，并配合 watch_start.c 的滑入动画（translate_y 作用于 parent）。 */
166	    lv_obj_set_size(parent, SCREEN_W, SCREEN_H);
167	    lv_obj_align(parent, LV_ALIGN_CENTER, 0, 0);
168	    lv_obj_set_style_bg_opa(parent, LV_OPA_TRANSP, 0);
169	    lv_obj_set_style_border_width(parent, 0, 0);
170	    lv_obj_set_style_pad_all(parent, 0, 0);
171	    lv_obj_clear_flag(parent, LV_OBJ_FLAG_SCROLLABLE);
172	
173	    create_background(parent);
174	    create_title();
175	    for (int8_t i = 0; i < APP_COUNT; i++) create_app_card(i);
176	    /* 初始全部默认态（不预选高亮） */
177	    for (int8_t i = 0; i < APP_COUNT; i++) set_card_default(i);
178	    selected_idx = 0;
179	    ui_group = lv_group_create();
180	    for (int8_t i = 0; i < APP_COUNT; i++) lv_group_add_obj(ui_group, ui_cards[i]);
181	}
182	
183	void app_launcher_next(void)  { selected_idx = (selected_idx+1) % APP_COUNT; for(int8_t i=0;i<APP_COUNT;i++) set_card_default(i); set_card_pressed(selected_idx); }
184	void app_launcher_prev(void)  { selected_idx = (selected_idx-1+APP_COUNT) % APP_COUNT; for(int8_t i=0;i<APP_COUNT;i++) set_card_default(i); set_card_pressed(selected_idx); }
185	void app_launcher_enter(void) { if (apps[selected_idx].launch_cb) apps[selected_idx].launch_cb(); }
186	int8_t app_launcher_get_selected(void) { return selected_idx; }
187	lv_group_t *app_launcher_get_group(void) { return ui_group; }
188	
189	void app_launcher_delete(void)
190	{
191	    if (ui_group) { lv_group_del(ui_group); ui_group = NULL; }
192	    if (ui_bg) { lv_obj_del(ui_bg); ui_bg = NULL; }
193	    /* 清空卡片/图标/名称数组引用，防悬空指针 */
194	    for (int8_t i = 0; i < APP_COUNT; i++) {
195	        ui_cards[i] = NULL; ui_icons[i] = NULL; ui_names[i] = NULL;
196	    }
197	    ui_ring = NULL; ui_title = NULL;
198	    selected_idx = 0;
199	}
200	
201	/* ========== 旧 API 适配：供 watch_start.c 页面栈调用 ==========
202	 * applist_create_list: 左滑/返回时建列表，内部委托 app_launcher_create。
203	 * applist_hide_page:   右滑/进二级页删列表前清理静态引用（group + ui_bg 子树），
204	 *                      调用方随后 lv_obj_delete(appListCenter) 删容器壳。 */
205	lv_obj_t *applist_create_list(lv_obj_t *scr)
206	{
207	    app_launcher_create(scr);
208	    return scr;
209	}
210	
211	void applist_hide_page(void)
212	{
213	    app_launcher_delete();  /* 删 group + ui_bg 子树，清空静态指针 */
214	    LV_LOG_USER("applist_hide_page: launcher cleaned");
215	}

