178	
179	/* ---- App tile ---- */
180	.app-tile {
181	  display: flex;
182	  flex-direction: column;
183	  align-items: center;
184	  justify-content: center;
185	  gap: 8px;
186	  background: var(--bg-card);
187	  border: 1px solid var(--stroke-soft);
188	  border-radius: var(--r-tile);
189	  cursor: pointer;
190	  transition: transform var(--dur-fast) var(--ease-spring), background var(--dur-fast);
191	}
192	.app-tile:active { transform: scale(0.93); }
193	.app-tile .ic { width: 40px; height: 40px; }
194	.app-tile .label { font-size: 13px; color: var(--text-secondary); font-weight: 500; }
195	
196	/* ---- Utility ---- */
197	.center-stack { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 24px; }
198	.glass-card {
199	  background: var(--bg-card);
200	  backdrop-filter: blur(14px);
201	  border: 1px solid var(--stroke-soft);
202	  border-radius: var(--r-card);
203	  box-shadow: var(--shadow-card);
204	}
205	.hint { font-size: 15px; color: var(--text-secondary); }
