104	    lv_obj_set_style_text_font(ui_title, font_manager_get_font(FONT_LARGE), 0);
105	    lv_obj_set_style_text_color(ui_title, TEXT_SECONDARY, 0);
106	    lv_obj_set_style_text_letter_space(ui_title, 1, 0);
107	    lv_obj_align(ui_title, LV_ALIGN_TOP_MID, 0, 60);
108	}
109	
110	/* ========== 单个应用磁贴 ==========
111	 * 设计稿：圆角矩形卡片，内含彩色圆角图标容器 + 下方文字。
112	 * 4 个应用排成 2×2 网格，整体居中。 */
113	static void create_app_tile(int8_t idx)
114	{
115	    int col = idx % GRID_COLS;
116	    int row = idx / GRID_COLS;
117	    int16_t x = GRID_X0 + col * (TILE_W + TILE_GAP) + TILE_W / 2;
118	    int16_t y = GRID_Y0 + row * (TILE_H + TILE_GAP) + TILE_H / 2;
119	
120	    /* --- 磁贴容器 --- */
121	    ui_tiles[idx] = lv_obj_create(ui_bg);
122	    lv_obj_set_size(ui_tiles[idx], TILE_W, TILE_H);
123	    lv_obj_align(ui_tiles[idx], LV_ALIGN_CENTER, x - SCREEN_W / 2, y - SCREEN_H / 2);
124	    lv_obj_set_style_radius(ui_tiles[idx], TILE_RADIUS, 0);
125	    lv_obj_set_style_bg_color(ui_tiles[idx], BG_CARD, 0);
126	    lv_obj_set_style_bg_opa(ui_tiles[idx], LV_OPA_COVER, 0);
127	    lv_obj_set_style_border_width(ui_tiles[idx], 1, 0);
128	    lv_obj_set_style_border_color(ui_tiles[idx], STROKE_SOFT, 0);
129	    lv_obj_set_style_pad_all(ui_tiles[idx], 0, 0);
130	    lv_obj_clear_flag(ui_tiles[idx], LV_OBJ_FLAG_SCROLLABLE);
131	
132	    /* --- 图标容器（彩色圆角方块）--- */
133	    ui_icon_wraps[idx] = lv_obj_create(ui_tiles[idx]);
134	    lv_obj_set_size(ui_icon_wraps[idx], ICON_SIZE, ICON_SIZE);
135	    lv_obj_align(ui_icon_wraps[idx], LV_ALIGN_TOP_MID, 0, 10);
136	    lv_obj_set_style_radius(ui_icon_wraps[idx], ICON_RADIUS, 0);
137	
138	    /* 半透明背景色：取 icon_bg 的 RGB，alpha 固定 ~18% (LV_OPA_18=46) */
139	    lv_obj_set_style_bg_color(ui_icon_wraps[idx], apps[idx].icon_bg, 0);
140	    lv_obj_set_style_bg_opa(ui_icon_wraps[idx], 46, 0);  /* ~18% opacity */
141	    lv_obj_set_style_border_width(ui_icon_wraps[idx], 0, 0);
142	    lv_obj_set_style_pad_all(ui_icon_wraps[idx], 0, 0);
143	    lv_obj_clear_flag(ui_icon_wraps[idx], LV_OBJ_FLAG_SCROLLABLE);
144	    lv_obj_clear_flag(ui_icon_wraps[idx], LV_OBJ_FLAG_CLICKABLE);
145	
146	    /* --- 图标（LVGL symbol 占位）--- */
147	    ui_icon_labels[idx] = lv_label_create(ui_icon_wraps[idx]);
148	    lv_label_set_text(ui_icon_labels[idx], apps[idx].icon);
149	    lv_obj_set_style_text_font(ui_icon_labels[idx], &lv_font_montserrat_26, 0);
150	    lv_obj_set_style_text_color(ui_icon_labels[idx], apps[idx].icon_color, 0);
151	    lv_obj_center(ui_icon_labels[idx]);
152	
153	    /* --- 应用名称 --- */
154	    ui_names[idx] = lv_label_create(ui_tiles[idx]);
155	    lv_label_set_text(ui_names[idx], apps[idx].name);
156	    lv_obj_set_style_text_font(ui_names[idx], font_manager_get_font(FONT_LARGE), 0);
157	    lv_obj_set_style_text_color(ui_names[idx], TEXT_SECONDARY, 0);
158	    lv_obj_align(ui_names[idx], LV_ALIGN_BOTTOM_MID, 0, -10);
159	
160	    lv_obj_add_event_cb(ui_tiles[idx], tile_event_cb, LV_EVENT_ALL, (void*)(intptr_t)idx);
161	}
162	
163	/* ========== 磁贴样式：默认态 / 按下态 ========== */
164	static void set_tile_default(int8_t i)
165	{
166	    lv_obj_set_style_bg_opa(ui_tiles[i], LV_OPA_COVER, 0);
167	    lv_obj_set_style_border_color(ui_tiles[i], STROKE_SOFT, 0);
168	    lv_obj_set_style_border_width(ui_tiles[i], 1, 0);
169	    lv_obj_set_style_text_color(ui_names[i], TEXT_SECONDARY, 0);
170	}
171	
172	static void set_tile_pressed(int8_t i)
173	{
174	    lv_obj_set_style_bg_opa(ui_tiles[i], LV_OPA_30, 0);
175	    lv_obj_set_style_bg_color(ui_tiles[i], apps[i].icon_color, 0);
176	    lv_obj_set_style_border_color(ui_tiles[i], apps[i].icon_color, 0);
177	    lv_obj_set_style_border_width(ui_tiles[i], 2, 0);
178	    lv_obj_set_style_text_color(ui_names[i], TEXT_PRIMARY, 0);
179	}
180	
181	static void tile_event_cb(lv_event_t *e)
182	{
183	    lv_event_code_t code = lv_event_get_code(e);
184	    int8_t idx = (int8_t)(intptr_t)lv_event_get_user_data(e);
185	    if (code == LV_EVENT_PRESSED) {
186	        set_tile_pressed(idx);
187	    } else if (code == LV_EVENT_RELEASED || code == LV_EVENT_PRESS_LOST) {
188	        set_tile_default(idx);
189	    } else if (code == LV_EVENT_CLICKED) {
190	        if (apps[idx].launch_cb) apps[idx].launch_cb();
191	    }
192	}
