194	/* ========== 底部分页圆点 ========== */
195	static void create_page_dots(void)
196	{
197	    int16_t dots_y = SCREEN_H / 2 + GRID_H / 2 + 30;
198	    int16_t dot_w = 6, dot_active_w = 16;
199	    int16_t total_w = dot_active_w + 6 + dot_w;
200	    int16_t x0 = (SCREEN_W - total_w) / 2;
201	
202	    /* 第一个点（active） */
203	    ui_dots[0] = lv_obj_create(ui_bg);
204	    lv_obj_set_size(ui_dots[0], dot_active_w, dot_w);
205	    lv_obj_align(ui_dots[0], LV_ALIGN_CENTER, x0 + dot_active_w / 2 - SCREEN_W / 2,
206	                 dots_y - SCREEN_H / 2);
207	    lv_obj_set_style_radius(ui_dots[0], 3, 0);
208	    lv_obj_set_style_bg_color(ui_dots[0], lv_color_hex(0x6C5CE7), 0);  /* brand-primary */
209	    lv_obj_set_style_bg_opa(ui_dots[0], LV_OPA_COVER, 0);
210	    lv_obj_set_style_border_width(ui_dots[0], 0, 0);
211	    lv_obj_clear_flag(ui_dots[0], LV_OBJ_FLAG_CLICKABLE);
212	
213	    /* 第二个点（inactive） */
214	    ui_dots[1] = lv_obj_create(ui_bg);
215	    lv_obj_set_size(ui_dots[1], dot_w, dot_w);
216	    lv_obj_align(ui_dots[1], LV_ALIGN_CENTER,
217	                 x0 + dot_active_w + 6 + dot_w / 2 - SCREEN_W / 2,
218	                 dots_y - SCREEN_H / 2);
219	    lv_obj_set_style_radius(ui_dots[1], 3, 0);
220	    lv_obj_set_style_bg_color(ui_dots[1], STROKE_SOFT, 0);
221	    lv_obj_set_style_bg_opa(ui_dots[1], LV_OPA_COVER, 0);
222	    lv_obj_set_style_border_width(ui_dots[1], 0, 0);
223	    lv_obj_clear_flag(ui_dots[1], LV_OBJ_FLAG_CLICKABLE);
224	}
