226	/* ========== 公开 API ========== */
227	void app_launcher_create(lv_obj_t *parent)
228	{
229	    lv_obj_set_size(parent, SCREEN_W, SCREEN_H);
230	    lv_obj_align(parent, LV_ALIGN_CENTER, 0, 0);
231	    lv_obj_set_style_bg_opa(parent, LV_OPA_TRANSP, 0);
232	    lv_obj_set_style_border_width(parent, 0, 0);
233	    lv_obj_set_style_pad_all(parent, 0, 0);
234	    lv_obj_clear_flag(parent, LV_OBJ_FLAG_SCROLLABLE);
235	
236	    create_background(parent);
237	    create_title();
238	    for (int8_t i = 0; i < APP_COUNT; i++) create_app_tile(i);
239	    for (int8_t i = 0; i < APP_COUNT; i++) set_tile_default(i);
240	    create_page_dots();
241	
242	    selected_idx = 0;
243	    ui_group = lv_group_create();
244	    for (int8_t i = 0; i < APP_COUNT; i++) lv_group_add_obj(ui_group, ui_tiles[i]);
245	}
246	
247	void app_launcher_next(void)  { selected_idx = (selected_idx+1) % APP_COUNT; for(int8_t i=0;i<APP_COUNT;i++) set_tile_default(i); set_tile_pressed(selected_idx); }
248	void app_launcher_prev(void)  { selected_idx = (selected_idx-1+APP_COUNT) % APP_COUNT; for(int8_t i=0;i<APP_COUNT;i++) set_tile_default(i); set_tile_pressed(selected_idx); }
249	void app_launcher_enter(void) { if (apps[selected_idx].launch_cb) apps[selected_idx].launch_cb(); }
250	int8_t app_launcher_get_selected(void) { return selected_idx; }
251	lv_group_t *app_launcher_get_group(void) { return ui_group; }
252	
253	void app_launcher_delete(void)
254	{
255	    if (ui_group) { lv_group_del(ui_group); ui_group = NULL; }
256	    if (ui_bg) { lv_obj_del(ui_bg); ui_bg = NULL; }
257	    for (int8_t i = 0; i < APP_COUNT; i++) {
258	        ui_tiles[i] = NULL; ui_icon_wraps[i] = NULL;
259	        ui_icon_labels[i] = NULL; ui_names[i] = NULL;
260	    }
261	    ui_dots[0] = NULL; ui_dots[1] = NULL;
262	    ui_title = NULL;
263	    selected_idx = 0;
264	}
